package com.kuaixietech.refunds;
import com.kuaixietech.security.DomainAccessGuard;
import com.kuaixietech.payments.OriginalPaymentRefundGateway;
import java.util.*;
import org.springframework.http.HttpStatus;
import org.springframework.stereotype.Service;
import org.springframework.web.server.ResponseStatusException;
import static com.kuaixietech.refunds.RefundModels.*;
@Service
public class RefundService {
 private com.kuaixietech.coupler.CouplerModeGate couplerMode;
 @org.springframework.beans.factory.annotation.Autowired public void couplerMode(com.kuaixietech.coupler.CouplerModeGate gate){this.couplerMode=gate;}

 private final RefundStore store;private final RefundTransactions transactions;private final DomainAccessGuard guard;private final OriginalPaymentRefundGateway gateway;
 public RefundService(RefundStore store,RefundTransactions transactions,DomainAccessGuard guard,OriginalPaymentRefundGateway gateway){this.store=store;this.transactions=transactions;this.guard=guard;this.gateway=gateway;}
 private Map<String,Object> own(String id,boolean admin){String user=admin?guard.requireAdmin():guard.requireActiveProfile();var row=store.refund(id);if(row==null||!admin&&!user.equals(row.get("user_id")))throw new ResponseStatusException(HttpStatus.NOT_FOUND,"REFUND_NOT_FOUND");return row;}
 public List<Map<String,Object>> eligible(){String user=guard.requireActiveProfile();var rows=store.db.queryForList("SELECT p.id,p.base_minor,p.payment_minor,p.payment_currency,p.merchant_snapshot,p.paid_at FROM t_currency_payments p JOIN t_currency_payment_receipts r ON r.payment_id=p.id AND r.merchant_id=p.merchant_id AND r.provider_transaction_id=p.provider_transaction_id AND r.base_minor=p.base_minor AND r.payment_minor=p.payment_minor AND r.payment_currency=p.payment_currency AND r.payment_minor_digits=2 WHERE p.user_id=? AND p.status='paid' AND p.base_currency='CNY' AND p.payment_currency='CNY' AND p.payment_minor_digits=2 AND NOT EXISTS(SELECT 1 FROM t_payment_refunds f WHERE f.payment_id=p.id AND f.active_slot=1) ORDER BY p.paid_at DESC,p.id DESC LIMIT 100",user);var result=new ArrayList<Map<String,Object>>();for(var row:rows){var merchant=store.merchant(row);if(!Set.of("wechat_native_v3","wechat_jsapi_v3","wechat_app_v3","alipay_rsa2").contains(merchant.adapter()))continue;result.add(Map.of("id",row.get("id"),"baseAmount",new java.math.BigDecimal(row.get("base_minor").toString()).movePointLeft(2).setScale(2).toPlainString(),"paymentAmount",new java.math.BigDecimal(row.get("payment_minor").toString()).movePointLeft(2).setScale(2).toPlainString(),"paymentCurrency","CNY","merchantName",merchant.name(),"paidAt",Objects.toString(RefundStore.time(row.get("paid_at")),"")));}return result;}
 public List<Map<String,Object>> list(boolean admin,int limit,int offset){String user=admin?guard.requireAdmin():guard.requireActiveProfile();if(limit<1||limit>100||offset<0)throw new IllegalArgumentException("REFUND_INVALID_PAGE");return (admin?store.db.queryForList("SELECT * FROM t_payment_refunds ORDER BY CASE WHEN status IN('requested','approved','dispatching','processing') THEN 0 ELSE 1 END,created_at DESC,id DESC LIMIT ? OFFSET ?",limit,offset):store.db.queryForList("SELECT * FROM t_payment_refunds WHERE user_id=? ORDER BY created_at DESC,id DESC LIMIT ? OFFSET ?",user,limit,offset)).stream().map(RefundStore::view).toList();}
 public List<Map<String,Object>> events(String id,boolean admin,int limit,int offset){own(id,admin);if(limit<1||limit>100||offset<0)throw new IllegalArgumentException("REFUND_INVALID_PAGE");return store.db.queryForList("SELECT id,action,detail,created_at AS createdAt FROM t_payment_refund_events WHERE refund_id=? ORDER BY created_at DESC,id DESC LIMIT ? OFFSET ?",id,limit,offset).stream().map(row->{var result=new LinkedHashMap<String,Object>(row);result.put("createdAt",RefundStore.time(row.get("createdAt")));return (Map<String,Object>)result;}).toList();}
 public Map<String,Object> detail(String id,boolean admin){return RefundStore.view(own(id,admin));}
 public Map<String,Object> create(Create input){return RefundStore.view(transactions.reserve(guard.requireActiveProfile(),input));}
 public Map<String,Object> review(String id,Review input){return RefundStore.view(transactions.review(id,guard.requireAdmin(),input));}
 public Map<String,Object> cancel(String id){var r=own(id,false);return RefundStore.view(transactions.cancel(id,r.get("user_id").toString()));}
 private Command command(Map<String,Object> r){return new Command(r.get("id").toString(),r.get("payment_id").toString(),r.get("provider_transaction_id").toString(),r.get("payment_currency").toString(),RefundStore.minor(r.get("payment_minor")),RefundStore.minor(r.get("payment_minor")),r.get("reason").toString());}
 public Map<String,Object> dispatch(String id){
  if(couplerMode!=null)couplerMode.requireLiveNewCall("payment_refund_dispatch");String actor=guard.requireAdmin();var r=own(id,true);if(!"approved".equals(r.get("status")))throw new ResponseStatusException(HttpStatus.CONFLICT,"REFUND_DISPATCH_NOT_ALLOWED");var merchant=store.merchant(r);if(!gateway.configured(merchant))throw new ResponseStatusException(HttpStatus.SERVICE_UNAVAILABLE,"REFUND_CHANNEL_NOT_CONFIGURED");gateway.prepare(merchant,command(r));r=transactions.claim(id,actor);try{return RefundStore.view(transactions.receipt(id,gateway.submit(merchant,command(r))));}catch(RuntimeException e){transactions.unconfirmed(id);return RefundStore.view(store.refund(id));}}
 public Map<String,Object> refresh(String id,boolean admin){var r=own(id,admin);if(!Set.of("dispatching","processing").contains(r.get("status")))return RefundStore.view(r);try{return RefundStore.view(transactions.receipt(id,gateway.query(store.merchant(r),command(r))));}catch(RuntimeException e){transactions.unconfirmed(id);return RefundStore.view(store.refund(id));}}
}
